//! Replays the pinned CesiumJS VoxelTraversal and Megatexture capture in
//! `tests/data/scene-voxel-traversal.json` (generated by
//! `tools/cesium/generate-scene-voxel-traversal.mjs`). The recording host
//! captures every texel upload, so octree and megatexture bytes are compared
//! exactly, along with the selected hierarchy, priorities and node state.
use cesium_rs::core::*;
use cesium_rs::renderer::*;
use cesium_rs::scene::*;
use serde_json::{json, Value};
use std::cell::{Cell, RefCell};
use std::rc::Rc;

const MAX_TEXTURE_SIZE: f64 = 0xD33 as f64;
const MAX_3D_TEXTURE_SIZE: f64 = 0x8073 as f64;
const MAX_COMBINED_TEXTURE_IMAGE_UNITS: f64 = 0x8B4D as f64;

#[derive(Clone, Default)]
struct Host {
    next: Rc<Cell<u32>>,
    uploads: Rc<RefCell<Vec<Value>>>,
}

impl Gl for Host {
    type Object = u32;
    fn drawing_buffer_size(&self) -> Result<[u32; 2], RuntimeError> {
        Ok([16, 16])
    }
    fn invoke(&self, name: &str, args: &[GlValue<u32>]) -> Result<GlValue<u32>, RuntimeError> {
        let number = |index: usize| match args.get(index) {
            Some(GlValue::Number(value)) => Some(*value),
            _ => None,
        };
        match (name, args) {
            ("texSubImage2D", [GlValue::Number(_), GlValue::Number(_level), GlValue::Number(x), GlValue::Number(y), GlValue::Number(w), GlValue::Number(h), _, _, GlValue::Pixels { bytes, .. }]) => {
                self.uploads.borrow_mut().push(json!({
                    "texture": "texture",
                    "x": x, "y": y, "z": 0,
                    "width": w, "height": h,
                    "bytes": bytes,
                }))
            }
            ("texSubImage3D", [GlValue::Number(_), GlValue::Number(_level), GlValue::Number(x), GlValue::Number(y), GlValue::Number(z), GlValue::Number(w), GlValue::Number(h), GlValue::Number(d), _, _, GlValue::Pixels { bytes, .. }]) => {
                self.uploads.borrow_mut().push(json!({
                    "texture": "texture3d",
                    "x": x, "y": y, "z": z,
                    "width": w, "height": h, "depth": d,
                    "bytes": bytes,
                }))
            }
            _ => {}
        }
        Ok(if name.starts_with("create") {
            self.next.set(self.next.get() + 1);
            GlValue::Object(self.next.get())
        } else {
            match name {
                "getParameter" => match number(0) {
                    Some(value) if value == 0x846D as f64 || value == 0x846E as f64 || value == 0xD3A as f64 => GlValue::Numbers(vec![1., 4096.]),
                    Some(value) if value == MAX_3D_TEXTURE_SIZE => GlValue::Number(2048.),
                    Some(value) if value == MAX_TEXTURE_SIZE => GlValue::Number(4096.),
                    Some(value) if value == MAX_COMBINED_TEXTURE_IMAGE_UNITS => GlValue::Number(32.),
                    _ => GlValue::Number(4096.),
                },
                "getExtension" => GlValue::Object(0),
                "getShaderParameter" | "getProgramParameter" => GlValue::Bool(true),
                "checkFramebufferStatus" => GlValue::Number(36053.),
                _ => GlValue::Null,
            }
        })
    }
}

fn fixture() -> Value {
    serde_json::from_str(include_str!("data/scene-voxel-traversal.json")).unwrap()
}

fn v3(value: &Value) -> Cartesian3 {
    Cartesian3::new(
        value[0].as_f64().unwrap(),
        value[1].as_f64().unwrap(),
        value[2].as_f64().unwrap(),
    )
}

struct Provider {
    transform: Matrix4,
    names: Vec<String>,
    types: Vec<MetadataType>,
    component_types: Vec<MetadataComponentType>,
    dimensions: Cartesian3,
}
impl VoxelProvider for Provider {
    fn global_transform(&self) -> &Matrix4 {
        &self.transform
    }
    fn shape_transform(&self) -> &Matrix4 {
        &self.transform
    }
    fn shape(&self) -> VoxelShapeType {
        VoxelShapeType::Box
    }
    fn min_bounds(&self) -> Option<Cartesian3> {
        None
    }
    fn max_bounds(&self) -> Option<Cartesian3> {
        None
    }
    fn dimensions(&self) -> Cartesian3 {
        self.dimensions
    }
    fn padding_before(&self) -> Cartesian3 {
        Cartesian3::ZERO
    }
    fn padding_after(&self) -> Cartesian3 {
        Cartesian3::ZERO
    }
    fn names(&self) -> &[String] {
        &self.names
    }
    fn types(&self) -> &[MetadataType] {
        &self.types
    }
    fn component_types(&self) -> &[MetadataComponentType] {
        &self.component_types
    }
    fn minimum_values(&self) -> Option<&[Vec<f64>]> {
        None
    }
    fn maximum_values(&self) -> Option<&[Vec<f64>]> {
        None
    }
    fn maximum_tile_count(&self) -> Option<usize> {
        Some(64)
    }
    fn available_levels(&self) -> Option<u32> {
        Some(2)
    }
    fn keyframe_count(&self) -> Option<u32> {
        Some(1)
    }
    fn time_interval_collection(&self) -> Option<&TimeIntervalCollection<u32>> {
        None
    }
    fn request_data(&mut self, request: VoxelRequest) -> Option<cesium_rs::scene::voxel_provider::VoxelFuture> {
        if request.tile_level >= 2 {
            return None;
        }
        let fill = request.tile_level as u8 + 1;
        let content = VoxelContent::from_metadata_array(vec![TypedArray::Uint8(vec![fill; 64])]);
        Some(Box::pin(async move { Ok(content) }))
    }
}

fn host() -> (Host, Rc<RefCell<Vec<Value>>>) {
    let uploads = Rc::new(RefCell::new(Vec::new()));
    (
        Host {
            next: Rc::new(Cell::new(0)),
            uploads: uploads.clone(),
        },
        uploads,
    )
}

fn frame_state(context: &Context<Host>, frame_number: u32, position: Cartesian3) -> FrameState {
    let mut camera = Camera::new(CameraOptions::new(16., 16.));
    camera.position = position;
    let mut uniform = camera.uniform_camera();
    uniform.position = position;
    let culling = CullingVolume::new(vec![
        Cartesian4::new(1.0, 0.0, 0.0, 100.0),
        Cartesian4::new(-1.0, 0.0, 0.0, 100.0),
        Cartesian4::new(0.0, 1.0, 0.0, 100.0),
        Cartesian4::new(0.0, -1.0, 0.0, 100.0),
        Cartesian4::new(0.0, 0.0, 1.0, 100.0),
        Cartesian4::new(0.0, 0.0, -1.0, 100.0),
    ]);
    let mut frame = FrameState::new(
        UniformFrame::new(uniform, JulianDate::new(2451545., 0., TimeStandard::Tai)),
        culling,
        [16, 16],
    );
    frame.frame_number = frame_number;
    frame.pixel_ratio = 1.0;
    frame.drawing_buffer_height = 1024;
    frame.context = Some(FrameResource::new(context.clone()));
    frame
}

#[allow(clippy::type_complexity)]
fn events() -> (Event<()>, Event<()>, Event<()>, Event<()>, Event<(usize, usize)>, Event<()>, Event<()>) {
    (
        Event::new(),
        Event::new(),
        Event::new(),
        Event::new(),
        Event::new(),
        Event::new(),
        Event::new(),
    )
}

fn check_node<G: Gl + 'static>(node: &SpatialNode, expected: &Value, traversal: &VoxelTraversal<G>, frame_number: u32) -> usize {
    let mut count = 1;
    assert_eq!(node.level, expected["level"].as_u64().unwrap() as u32);
    assert_eq!(node.coords, [0usize, 1, 2].map(|i| expected["coords"][i].as_u64().unwrap() as u32));
    let sse = node.screen_space_error;
    let expected_sse = expected["screenSpaceError"].as_f64().unwrap();
    assert!((sse - expected_sse).abs() < 1e-9, "{sse} != {expected_sse}");
    assert_eq!(node.visited_frame_number, expected["visited"].as_i64().unwrap());
    assert_eq!(node.parent_screen_space_error.is_finite(), expected_sse.is_finite());
    assert_eq!(traversal.is_renderable(node), expected["renderable"].as_bool().unwrap());
    for (slot, key) in [(node.previous.as_ref(), "previous"), (node.next.as_ref(), "next")] {
        let expected_slot = &expected[key];
        if expected_slot.is_null() {
            assert!(slot.is_none(), "{key}");
        } else {
            let slot = slot.unwrap();
            assert_eq!(slot.level, expected_slot["level"].as_u64().unwrap() as u32, "{key} level");
            assert_eq!(slot.keyframe, expected_slot["keyframe"].as_f64().unwrap(), "{key} keyframe");
        }
    }
    let _ = frame_number;
    if let Some(keyframes) = expected["keyframes"].as_array() {
        assert_eq!(node.keyframe_nodes.len(), keyframes.len());
        for (keyframe, expected_keyframe) in node.keyframe_nodes.iter().zip(keyframes) {
            assert_eq!(keyframe.keyframe, expected_keyframe["keyframe"].as_f64().unwrap());
            assert_eq!(keyframe.state as u8 as u64, expected_keyframe["state"].as_u64().unwrap());
            let expected_priority = expected_keyframe["priority"].as_f64().unwrap();
            if expected_priority.is_finite() {
                assert!(
                    (keyframe.priority - expected_priority).abs() < 1e-9,
                    "priority {} != {expected_priority}",
                    keyframe.priority
                );
            }
            assert_eq!(keyframe.megatexture_index, expected_keyframe["megatextureIndex"].as_i64().unwrap() as isize, "megatexture index for level {} coords {:?}", node.level, node.coords);
        }
    }
    match expected["children"].as_array() {
        Some(children) => {
            let actual = node.children.as_ref().expect("children expected");
            assert_eq!(actual.len(), children.len());
            for (child, expected_child) in actual.iter().zip(children) {
                count += check_node(child, expected_child, traversal, frame_number);
            }
        }
        None => assert!(node.children.is_none()),
    }
    count
}

#[test]
fn traversal_hierarchy_keyframes_and_texels_match_pinned_cesium() {
    let _ = events;
    let (recording_host, uploads) = host();
    let context = Context::new_webgl2(recording_host);
    let shape_type = VoxelShapeType::Box;
    let mut shape = shape_type.create_shape();
    assert!(shape.update(
        Matrix4::IDENTITY,
        Cartesian3::new(-1., -1., -1.),
        Cartesian3::new(1., 1., 1.),
        Some(Cartesian3::new(-1., -1., -1.)),
        Some(Cartesian3::new(1., 1., 1.)),
    ));
    let mut provider = Provider {
        transform: Matrix4::IDENTITY,
        names: vec!["density".into()],
        types: vec![MetadataType::Scalar],
        component_types: vec![MetadataComponentType::Uint8],
        dimensions: Cartesian3::new(2., 2., 2.),
    };
    let mut traversal = VoxelTraversal::new(
        &context,
        Cartesian3::new(2., 2., 2.),
        Cartesian3::new(4., 4., 4.),
        1,
        provider.types(),
        provider.component_types(),
        shape.as_ref(),
        1,
        Some(8 * 1024 * 1024),
        Some(64),
        false,
    )
    .unwrap();
    let construction = &fixture()["construction"];
    assert_eq!(traversal.internal_node_tiles_per_row, construction["internalNodeTilesPerRow"].as_u64().unwrap() as usize);
    assert_eq!(
        traversal.internal_node_texel_size_uv.x,
        construction["internalNodeTexelSizeUv"][0].as_f64().unwrap()
    );
    assert_eq!(
        traversal.internal_node_texel_size_uv.y,
        construction["internalNodeTexelSizeUv"][1].as_f64().unwrap()
    );
    assert_eq!(
        traversal.texture_memory_byte_length,
        construction["textureMemoryByteLength"].as_u64().unwrap() as usize
    );
    let expected_megatexture = &construction["megatextures"][0];
    assert_eq!(
        traversal.megatextures[0].maximum_tile_count,
        expected_megatexture["maximumTileCount"].as_u64().unwrap() as usize
    );
    assert_eq!(traversal.megatextures[0].tile_counts, v3(&expected_megatexture["tileCounts"]));

    let mut statistics = Cesium3DTilesetStatistics::new();
    let mut initial_loaded = false;
    for step in fixture()["steps"].as_array().unwrap() {
        let expected_frame = step["frameNumber"].as_u64().unwrap() as u32;
        uploads.borrow_mut().clear();
        for frame_number in [expected_frame.saturating_sub(1), expected_frame] {
        {
            let mut frame = frame_state(&context, frame_number, Cartesian3::new(2.5, 2.5, 8.0));
            let (mut load, mut visible, mut failed, mut unload, mut progress, mut all, mut initial) = events();
            let mut event_sink = VoxelTraversalEvents {
                tile_load: &mut load,
                tile_visible: &mut visible,
                tile_failed: &mut failed,
                tile_unload: &mut unload,
                load_progress: &mut progress,
                all_tiles_loaded: &mut all,
                initial_tiles_loaded: &mut initial,
            };
            traversal.set_keyframe_location(step["keyframeLocation"].as_f64().unwrap());
            traversal
                .update(
                    &mut frame,
                    &CullingVolume::new(vec![
                        Cartesian4::new(1.0, 0.0, 0.0, 100.0),
                        Cartesian4::new(-1.0, 0.0, 0.0, 100.0),
                        Cartesian4::new(0.0, 1.0, 0.0, 100.0),
                        Cartesian4::new(0.0, -1.0, 0.0, 100.0),
                        Cartesian4::new(0.0, 0.0, 1.0, 100.0),
                        Cartesian4::new(0.0, 0.0, -1.0, 100.0),
                    ]),
                    &mut provider,
                    shape.as_ref(),
                    VoxelTraversalSettings {
                        level_blend_factor: 0.0,
                        screen_space_error: 4.0,
                        calculate_statistics: false,
                        pause_update: false,
                        recompute_bounding_volumes: false,
                        frame_number,
                        camera_position: Cartesian3::new(2.5, 2.5, 8.0),
                        drawing_buffer_height: 1024.0,
                        pixel_ratio: 1.0,
                        sse_denominator: 1.0,
                    },
                    &mut statistics,
                    &mut event_sink,
                    None,
                )
                .unwrap();
        }
        }
        let frame_number = expected_frame;
        assert_eq!(traversal.frame_number, frame_number);
        assert_eq!(traversal.sample_count, Some(step["sampleCount"].as_u64().unwrap() as usize));
        let nodes = check_node(&traversal.root_node, &step["root"], &traversal, frame_number);
        assert!(nodes >= 1);
        let expected_high = step["highPriority"].as_array().unwrap();
        assert_eq!(traversal.high_priority_keyframe_node_count, expected_high.len());
        for (actual, expected) in traversal
            .high_priority_keyframe_nodes
            .iter()
            .take(traversal.high_priority_keyframe_node_count)
            .zip(expected_high)
        {
            assert_eq!(actual.keyframe, expected["keyframe"].as_f64().unwrap());
            let expected_priority = expected["priority"].as_f64().unwrap();
            assert!((actual.priority - expected_priority).abs() < 1e-9);
            assert_eq!(actual.high_priority_frame_number, expected["highPriorityFrameNumber"].as_i64().unwrap());
            let spatial = {
                let mut node = &traversal.root_node;
                for index in &actual.path {
                    node = &node.children.as_ref().unwrap()[*index as usize];
                }
                node
            };
            assert_eq!(spatial.level, expected["level"].as_u64().unwrap() as u32);
            assert_eq!(spatial.coords, [0usize, 1, 2].map(|i| expected["coords"][i].as_u64().unwrap() as u32));
            assert_eq!(spatial.keyframe_nodes[0].state as u8 as u64, expected["state"].as_u64().unwrap());
            assert_eq!(
                spatial.keyframe_nodes[0].megatexture_index,
                expected["megatextureIndex"].as_i64().unwrap() as isize
            );
        }
        let expected_writes = step["writes"].as_array().unwrap();
        let actual = uploads.borrow();
        assert_eq!(actual.len(), expected_writes.len(), "upload count for frame {frame_number}");
        for (actual, expected) in actual.iter().zip(expected_writes) {
            assert_eq!(actual["texture"], expected["texture"]);
            assert_eq!(actual["x"].as_f64().unwrap(), expected["x"].as_f64().unwrap());
            assert_eq!(actual["y"].as_f64().unwrap(), expected["y"].as_f64().unwrap());
            assert_eq!(actual["z"].as_f64().unwrap(), expected["z"].as_f64().unwrap());
            assert_eq!(actual["width"].as_f64().unwrap(), expected["width"].as_f64().unwrap());
            assert_eq!(actual["height"].as_f64().unwrap(), expected["height"].as_f64().unwrap());
            let expected_bytes: Vec<u8> = expected["bytes"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as u8).collect();
            let actual_bytes: Vec<u8> = actual["bytes"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as u8).collect();
            assert_eq!(actual_bytes, expected_bytes, "texels for frame {frame_number}");
        }
    }
    assert!(!initial_loaded);
    initial_loaded = true;
    let _ = initial_loaded;
    traversal.destroy().unwrap();
}
